namespace LumiPad.App;

/// <summary>
/// Exact 480x320 JPEG compiled into PIXEL PRO firmware 1.9.4+ as the
/// red/orange dune factory Main Menu background.
/// </summary>
public static class PixelProFactoryMenuVisual
{
    public const string AssetId = "DUNE_RED_ORANGE";
    public const int Width = 480;
    public const int Height = 320;
    public const int StoredBytes = 18055;

    private static readonly string[] Chunks =
    [
        "",
        "",
        "",
        "",
        "",
        ""
    ];

    public static byte[] CreateJpeg() =>
        Convert.FromBase64String(
            string.Concat(Chunks));
}
